682	// ---- 持久化 ----
683	
684	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
685	func (s *Store) loadLocked() (*storedState, error) {
686		raw, err := os.ReadFile(s.path)
687		if err != nil {
688			return nil, err
689		}
690		if len(bytes.TrimSpace(raw)) == 0 {
691			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
692		}
693		if err := rejectDuplicateKeys(raw); err != nil {
694			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
695		}
696		var state storedState
697		dec := json.NewDecoder(bytes.NewReader(raw))
698		dec.DisallowUnknownFields()
699		if err := dec.Decode(&state); err != nil {
700			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
701		}
702		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
703		var extra json.RawMessage
704		if err := dec.Decode(&extra); err != io.EOF {
705			if err == nil {
706				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
707			}
708			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
709		}
710		if err := validateState(&state); err != nil {
711			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
712		}
713		return &state, nil
714	}
715	
716	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
717	// 任一步失败都保留上次完整状态。调用方必须持锁。
718	func (s *Store) commitLocked(state *storedState) error {
719		if err := validateState(state); err != nil {
720			return fmt.Errorf("refusing to persist invalid state: %w", err)
721		}
722		payload, err := json.MarshalIndent(state, "", "  ")
723		if err != nil {
724			return err
725		}
726		payload = append(payload, '\n')
727	
728		dir := filepath.Dir(s.path)
729		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
730		if err != nil {
731			return err
732		}
733		tmpName := tmp.Name()
734		cleanup := func() { _ = os.Remove(tmpName) }
735		if _, err := tmp.Write(payload); err != nil {
736			_ = tmp.Close()
737			cleanup()
738			return err
739		}
740		if err := tmp.Sync(); err != nil {
741			_ = tmp.Close()
742			cleanup()
743			return err
744		}
745		if err := tmp.Close(); err != nil {
746			cleanup()
747			return err
748		}
749		if err := os.Chmod(tmpName, 0o600); err != nil {
750			cleanup()
751			return err
752		}
753		if err := os.Rename(tmpName, s.path); err != nil {
754			cleanup()
755			return err
756		}
757		if err := syncDir(dir); err != nil {
758			return err
759		}
760		return nil
761	}
762	
763	func syncDir(dir string) error {
764		d, err := os.Open(dir)
765		if err != nil {
766			return err
767		}
768		defer d.Close()
769		return d.Sync()
770	}
771	
772	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
773	func validateState(state *storedState) error {
774		if state.Magic != stateMagic {
775			return fmt.Errorf("bad magic %q", state.Magic)
776		}
777		if state.Version != stateVersion {
778			return fmt.Errorf("unsupported state version %d", state.Version)
779		}
780		if state.InitialTreasury < 0 {
781			return errors.New("initial treasury balance is negative")
782		}
783		if state.Treasury < 0 {
784			return errors.New("treasury balance is negative")
785		}
786		if state.Balances == nil {
787			return errors.New("balances table is missing")
788		}
789		if state.Proposals == nil {
790			return errors.New("proposals table is missing")
791		}
792		if state.Receipts == nil {
793			return errors.New("receipts table is missing")
794		}
795		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
796		if state.VoteProposals == nil {
797			state.VoteProposals = map[string]*storedVoteProposal{}
798		}
799		for account, balance := range state.Balances {
800			if account == "" {
801				return errors.New("balance entry with empty account")
802			}
803			if balance < 0 {
804				return fmt.Errorf("balance of %q is negative", account)
805			}
806		}
807		for key, p := range state.Proposals {
808			if p == nil {
809				return fmt.Errorf("proposal %q is empty", key)
810			}
811			if p.ID != key || p.ID == "" {
812				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
813			}
814			if p.State != "passed" && p.State != "executed" {
815				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
816			}
817			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
818		}
819		if err := validateVoteProposals(state); err != nil {
820			return err
821		}
822	
823		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
824		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
825		simTreasury := state.InitialTreasury
826		simBalances := map[string]int64{}
827		seenReceipts := map[string]int{}
828		for order, rcpt := range state.Receipts {
829			if rcpt == nil {
830				return fmt.Errorf("receipt %d is empty", order)
831			}
832			if rcpt.Order != order {
833				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
834			}
835			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
836				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
837			}
838			seenReceipts[rcpt.ProposalID] = order
839			ownerState, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
840			if !found {
841				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
842			}
843			if ownerState != "executed" {
844				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
845			}
846			if len(rcpt.Actions) != len(ownerActions) {
847				return fmt.Errorf("receipt %q action count %d does not match proposal %d", rcpt.ProposalID, len(rcpt.Actions), len(ownerActions))
848			}
849			for i, ar := range rcpt.Actions {
850				if ar.Index != i {
851					return fmt.Errorf("receipt %q action %d has index %d", rcpt.ProposalID, i, ar.Index)
852				}
853				if ar.Action != ownerActions[i] {
854					return fmt.Errorf("receipt %q action %d text does not match registered action", rcpt.ProposalID, i)
855				}
856				account, amount, err := ParseTransfer(ar.Action)
857				if err != nil {
858					return fmt.Errorf("receipt %q action %d is not executable: %v", rcpt.ProposalID, i, err)
859				}
860				if ar.Treasury.Account != "treasury" || ar.Treasury.Before != simTreasury {
861					return fmt.Errorf("receipt %q action %d treasury before-balance mismatch", rcpt.ProposalID, i)
862				}
863				if simTreasury < amount || ar.Treasury.After != simTreasury-amount {
864					return fmt.Errorf("receipt %q action %d treasury after-balance mismatch", rcpt.ProposalID, i)
865				}
866				before := simBalances[account]
867				if ar.Recipient.Account != account || ar.Recipient.Before != before {
868					return fmt.Errorf("receipt %q action %d recipient before-balance mismatch", rcpt.ProposalID, i)
869				}
870				after, ok := addInt64(before, amount)
871				if !ok || ar.Recipient.After != after {
872					return fmt.Errorf("receipt %q action %d recipient after-balance mismatch", rcpt.ProposalID, i)
873				}
874				simTreasury -= amount
875				simBalances[account] = after
876			}
877		}
878		if simTreasury != state.Treasury {
879			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
880		}
881		if len(simBalances) != len(state.Balances) {
882			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
883		}
884		for account, balance := range state.Balances {
885			if simBalances[account] != balance {
886				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
887			}
888		}
889		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
890		for _, p := range state.Proposals {
891			_, hasReceipt := seenReceipts[p.ID]
892			if p.State == "executed" && !hasReceipt {
893				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
894			}
895		}
896		for _, p := range state.VoteProposals {
897			_, hasReceipt := seenReceipts[p.ID]
898			if p.State == "executed" && !hasReceipt {
899				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
900			}
901		}
902		return nil
903	}
904	
905	// scanFrame 是重复键扫描的栈帧。
906	type scanFrame struct {
907		isArray bool
908		seen    map[string]bool
909		atValue bool // 对象帧：下一个待消费 token 是值而非键
910	}
911	
912	func rejectDuplicateKeys(raw []byte) error {
913		dec := json.NewDecoder(bytes.NewReader(raw))
914		var stack []*scanFrame
915		for {
916			tok, err := dec.Token()
917			if err == io.EOF {
918				if len(stack) != 0 {
919					return errors.New("unterminated object or array")
920				}
921				return nil
922			}
923			if err != nil {
924				return err
925			}
926			switch t := tok.(type) {
927			case json.Delim:
928				switch t {
929				case '{':
930					stack = append(stack, &scanFrame{seen: map[string]bool{}})
931					continue
932				case '[':
933					stack = append(stack, &scanFrame{isArray: true})
934					continue
935				case '}', ']':
936					if len(stack) == 0 {
937						return errors.New("unexpected closing delimiter")
938					}
939					stack = stack[:len(stack)-1]
940					// 关闭的容器本身是外层对象的某个“值”，消费完毕后外层等待下一个键。
941					if len(stack) > 0 && !stack[len(stack)-1].isArray {
942						stack[len(stack)-1].atValue = false
943					}
944					continue
945				}
946			default:
947				// 标量 token。
948			}
949			if len(stack) > 0 && !stack[len(stack)-1].isArray {
950				frame := stack[len(stack)-1]
951				if !frame.atValue {
952					key, ok := tok.(string)
953					if !ok {
954						return errors.New("object key must be a string")
955					}
956					if frame.seen[key] {
957						return fmt.Errorf("duplicate key %q", key)
958					}
959					frame.seen[key] = true
960					frame.atValue = true
961				} else {
962					frame.atValue = false
963				}
964			}
965		}
966	}
967

