821	func TestTamperedVoteStateRejected(t *testing.T) {
822		dir := t.TempDir()
823		path := filepath.Join(dir, "treasury.json")
824		store, err := InitTreasury(path, 1000)
825		if err != nil {
826			t.Fatal(err)
827		}
828		in := baseVoteInput("gip-tamper")
829		mustCreateVote(t, store, in)
830		if _, err := store.CastVote("gip-tamper", "alice", true, 150); err != nil {
831			t.Fatal(err)
832		}
833		if _, err := store.TallyVote("gip-tamper", 200); err != nil {
834			t.Fatal(err)
835		}
836		store.Close()
837	
838		good, err := os.ReadFile(path)
839		if err != nil {
840			t.Fatal(err)
841		}
842		// 用结构化改写构造损坏变体，避免依赖具体缩进。
843		mutate := func(fn func(p map[string]any)) []byte {
844			var clone map[string]any
845			if err := json.Unmarshal(good, &clone); err != nil {
846				t.Fatal(err)
847			}
848			p := clone["vote_proposals"].(map[string]any)["gip-tamper"].(map[string]any)
849			fn(p)
850			raw, err := json.MarshalIndent(clone, "", "  ")
851			if err != nil {
852				t.Fatal(err)
853			}
854			return append(raw, '\n')
855		}
856		cases := map[string][]byte{
857			"ballot weight mismatch": mutate(func(p map[string]any) {
858				p["ballots"].([]any)[0].(map[string]any)["weight"] = 601
859			}),
860			"ballot from non-head": mutate(func(p map[string]any) {
861				p["ballots"].([]any)[0].(map[string]any)["representative"] = "bob"
862			}),
863			"duplicate ballot rep": mutate(func(p map[string]any) {
864				extra := map[string]any{"representative": "alice", "weight": 600, "support": true, "voted_at": 151}
865				p["ballots"] = append(p["ballots"].([]any), extra)
866			}),
867			"tally before deadline": mutate(func(p map[string]any) {
868				p["tally"].(map[string]any)["tallied_at"] = 199
869			}),
870			"tally disagrees with ballots": mutate(func(p map[string]any) {
871				p["tally"].(map[string]any)["for_weight"] = 601
872			}),
873			"unknown vote state": mutate(func(p map[string]any) {
874				p["state"] = "approved"
875			}),
876			"quorum out of range": mutate(func(p map[string]any) {
877				p["quorum"] = 1001
878			}),
879		}
880		// id collision：在 register 来源表里注入同一编号。
881		collision := mutate(func(p map[string]any) {})
882		var cd map[string]any
883		if err := json.Unmarshal(collision, &cd); err != nil {
884			t.Fatal(err)
885		}
886		cd["proposals"] = map[string]any{"gip-tamper": map[string]any{
887			"id": "gip-tamper", "state": "passed", "timelock_end": 300,
888			"actions": []any{"transfer:audits:100"},
889		}}
890		if raw, err := json.MarshalIndent(cd, "", "  "); err != nil {
891			t.Fatal(err)
892		} else {
893			cases["id collision"] = append(raw, '\n')
894		}
895		for name, raw := range cases {
896			t.Run(name, func(t *testing.T) {
897				bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
898				if err := os.WriteFile(bad, raw, 0o600); err != nil {
899					t.Fatal(err)
900				}
901				s, err := Open(bad)
902				if !errors.Is(err, ErrStateCorrupt) {
903					if s != nil {
904						s.Close()
905					}
906					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
907				}
908				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(raw) {
909					t.Fatalf("corrupt file was modified")
910				}
911			})
912		}
913	}
