1000			t.Fatalf("ballots = %+v", va.Ballots)
1001		}
1002	
1003		// 返回的是副本：改写快照不影响后续查询。
1004		snap.Registered[0].State = "executed"
1005		snap.Voting[0].State = "executed"
1006		again, err := store.ProposalsSnapshot()
