1015	func TestProposalsSnapshotConsistentUnderConcurrentExecute(t *testing.T) {
1016		store, _ := openTempStore(t, 1000)
1017		defer store.Close()
1018		// 登记提案与投票提案最初都为 passed 且时间锁已到期；
1019		// 执行方先执行登记提案，再执行投票提案。快照只允许出现
1020		// (passed,passed)、(executed,passed)、(executed,executed) 三种完整组合，
1021		// 不得出现登记提案仍为 passed 而投票提案已 executed 的混杂状态。
1022		mustRegister(t, store, "gip-reg", 0, "transfer:audits:100")
1023		mustCreateVote(t, store, baseVoteInput("gip-vote"))
1024		if _, err := store.CastVote("gip-vote", "alice", true, 100); err != nil {
1025			t.Fatalf("CastVote: %v", err)
1026		}
1027		if _, err := store.TallyVote("gip-vote", 200); err != nil {
1028			t.Fatalf("TallyVote: %v", err)
1029		}
1030	
1031		var wg sync.WaitGroup
1032		start := make(chan struct{})
1033		stop := make(chan struct{})
1034		wg.Add(1)
1035		go func() {
1036			defer wg.Done()
1037			<-start
1038			_, _ = store.Execute("gip-reg", 300)
1039			_, _ = store.Execute("gip-vote", 300)
1040			close(stop)
1041		}()
1042		for i := 0; i < 8; i++ {
1043			wg.Add(1)
1044			go func() {
1045				defer wg.Done()
1046				<-start
1047				for {
1048					select {
1049					case <-stop:
1050						return
1051					default:
1052					}
1053					snap, err := store.ProposalsSnapshot()
1054					if err != nil {
1055						t.Errorf("ProposalsSnapshot: %v", err)
1056						return
1057					}
1058					if len(snap.Registered) != 1 || len(snap.Voting) != 1 {
1059						t.Errorf("snapshot sizes = %d/%d, want 1/1", len(snap.Registered), len(snap.Voting))
1060						return
1061					}
1062					reg := snap.Registered[0].State
1063					vote := snap.Voting[0].State
1064					if reg == "passed" && vote == "executed" {
1065						t.Errorf("mixed committed states: registered=%s voting=%s", reg, vote)
1066						return
1067					}
1068				}
1069			}()
1070		}
1071		close(start)
1072		wg.Wait()
1073	}
