55		// 再多 1：明确报权重溢出，两侧与提案其余内容保持原样。
56		err := Vote(p, 1, true)
57		if err == nil || !strings.Contains(err.Error(), "overflow") {
58			t.Fatalf("overflow vote must report weight overflow, got %v", err)
59		}
60		if p.ForVotes != max || p.AgainstVotes != 0 {
61			t.Fatalf("failed overflow vote changed totals: %d/%d", p.ForVotes, p.AgainstVotes)
62		}
63		if p.State != "voting" {
64			t.Fatalf("failed overflow vote changed state: %s", p.State)
65		}
66	
67		// 失败不挪到另一侧：反对侧仍能被容纳。
68		if err := Vote(p, 1, false); err != nil {
69			t.Fatalf("against-side vote after for-side overflow must be accepted: %v", err)
70		}
71		if p.ForVotes != max || p.AgainstVotes != 1 {
72			t.Fatalf("totals = %d/%d, want %d/1", p.ForVotes, p.AgainstVotes, max)
73		}
74	
75		// 先差 10 到顶：11 溢出失败后，10 仍应被接受并恰好到顶，不截断也不变负。
76		q := &Proposal{ID: "q", State: "voting", Quorum: 1}
77		if err := Vote(q, max-10, false); err != nil {
78			t.Fatal(err)
79		}
80		if err := Vote(q, 11, false); err == nil {
81			t.Fatal("vote exceeding the cap must be rejected")
82		}
83		if q.AgainstVotes != max-10 {
84			t.Fatalf("rejected vote saturated/clamped totals: %d", q.AgainstVotes)
85		}
86		if err := Vote(q, 10, false); err != nil {
87			t.Fatalf("fittable vote after overflow failure must be accepted: %v", err)
88		}
89		if q.AgainstVotes != max {
90			t.Fatalf("against = %d, want %d", q.AgainstVotes, max)
91		}
92	}
