121		atQuorum := &Proposal{ID: "q", State: "voting", ForVotes: max - 1, AgainstVotes: 1, Quorum: max}
122		if got := Tally(atQuorum); got != "passed" {
123			t.Fatalf("Tally = %q, want passed (turnout == quorum)", got)
124		}
125	
