127		low := &Proposal{ID: "l", State: "voting", ForVotes: 400, AgainstVotes: 0, Quorum: 700}
128		if got := Tally(low); got != "rejected" {
129			t.Fatalf("Tally = %q, want rejected on low turnout", got)
130		}
131	
132		// 计票只返回结论：不改写状态、票数。
133		if p.State != "voting" || p.ForVotes != max || p.AgainstVotes != 1 {
134			t.Fatalf("Tally mutated proposal: %+v", p)
135		}
